using System.Globalization;
namespace PSiptv.Services;

public static class LanguageService
{
    private static readonly CultureInfo systemCulture = CultureInfo.CurrentUICulture;
    public static string DisplayName => Preferences.Default.Get("language", "system") switch { "en" => "English", "pt" => "Português", _ => "Do sistema" };
    public static void Apply(string? language = null)
    {
        if (language is not null) Preferences.Default.Set("language", language);
        var selected = Preferences.Default.Get("language", "system");
        var culture = selected switch { "en" => new CultureInfo("en-GB"), "pt" => new CultureInfo("pt-PT"), _ => systemCulture };
        CultureInfo.DefaultThreadCurrentCulture = culture; CultureInfo.DefaultThreadCurrentUICulture = culture;
        CultureInfo.CurrentCulture = culture; CultureInfo.CurrentUICulture = culture;
    }
    public static async Task<string> ActionSheetAsync(Page page, string title, string? cancel, string? destruction, params string[] buttons)
    {
        var labels = buttons.Select(Text).ToArray();
        var answer = await page.DisplayActionSheetAsync(Text(title), cancel is null ? null : Text(cancel), destruction is null ? null : Text(destruction), labels);
        var index = Array.IndexOf(labels, answer); return index < 0 ? answer : buttons[index];
    }
    public static Task AlertAsync(Page page, string title, string message, string cancel = "OK") =>
        page.DisplayAlertAsync(Text(title), Text(message), Text(cancel));
    public static Task<bool> ConfirmAsync(Page page, string title, string message, string accept, string cancel) =>
        page.DisplayAlertAsync(Text(title), Text(message), Text(accept), Text(cancel));
    public static string Format(string template, params object?[] values) =>
        string.Format(CultureInfo.CurrentCulture, Text(template), values);
    public static string Text(string text)
    {
        if (CultureInfo.CurrentUICulture.TwoLetterISOLanguageName != "en") return text;
        var suffix = text.EndsWith("  ›") ? "  ›" : "";
        var key = suffix.Length > 0 ? text[..^3] : text;
        if (translations.TryGetValue(key, out var value)) return value + suffix;
        var patterns = new (string Pattern, string Replacement)[]
        {
            (@"^(\d+) conteúdos · Selecione para reproduzir\.$", "$1 items · Select to play."),
            (@"^Todas as categorias \((\d+)\)$", "All categories ($1)"),
            (@"^(\d+) episódios · Organizados por temporada$", "$1 episodes · Organized by season"),
            (@"^(\d+) programas · Horário local do dispositivo$", "$1 programmes · Device local time"),
            (@"^(\d+) canais · Selecione um canal para reproduzir\.$", "$1 channels · Select a channel to play."),
            (@"^(\d+) s entre episódios$", "$1 seconds between episodes"),
            (@"^(\d+) segundos de cache de rede$", "$1 seconds of network cache"),
            (@"^(.+) s entre episódios$", "$1 seconds between episodes"),
            (@"^(.+) segundos de cache de rede$", "$1 seconds of network cache"),
            (@"^Versão: (.+)$", "Version: $1"),
            (@"^(\d+) conteúdos$", "$1 items"),
            (@"^(.+) · (\d+) conteúdos$", "$1 · $2 items"),
            (@"^(\d+) canais favoritos · Selecione para reproduzir\.$", "$1 favourite channels · Select to play."),
            (@"^(\d+) canais · Escolha um canal para consultar a programação\.$", "$1 channels · Choose a channel to view its schedule."),
            (@"^Foram encontrados (\d+) canais\.$", "$1 channels were found."),
            (@"^Foram encontrados (\d+) programas\.$", "$1 programmes were found."),
            (@"^«(.+)» respondeu HTTP (.+)$", "‘$1’ responded with HTTP $2"),
            (@"^(\d+) downloads · (.+) offline$", "$1 downloads · $2 offline"),
            (@"^Aguarde (\d+) segundos antes de tentar novamente\.$", "Wait $1 seconds before trying again."),
            (@"^Próximo episódio em (\d+) s · (.+)$", "Next episode in $1 s · $2"),
            (@"^([0-9.,]+) Mbps · transmissão$", "$1 Mbps · stream"),
            (@"^Eliminar «(.+)» deste dispositivo\?$", "Delete ‘$1’ from this device?"),
            (@"^Remover «(.+)»\?$", "Remove ‘$1’?"),
            (@"^Proporção do ecrã: (.+)$", "Screen aspect ratio: $1")
            ,(@"^Episódio (.+)$", "Episode $1")
            ,(@"^Temporada (.+)$", "Season $1")
            ,(@"^Canal (\d+)$", "Channel $1")
            ,(@"^(.+) · Protegida com PIN$", "$1 · PIN protected")
            ,(@"^(.+) · Sem PIN$", "$1 · No PIN")
        };
        foreach (var (pattern, replacement) in patterns) if (System.Text.RegularExpressions.Regex.IsMatch(key, pattern)) return System.Text.RegularExpressions.Regex.Replace(key, pattern, replacement) + suffix;
        return key + suffix;
    }
